1	// The FRESHNESS half of the fleet-roster sweep: the `fleet-drift` issue family, the
2	// root-cause classification behind it, and the freshness section of the run report.
3	//
4	// It holds no enumeration and no membership classification — the roster is built once,
5	// for both halves, by its sibling check-fleet-roster.mjs, which hands this module only
6	// the members it has already established are covered, awake, in scope and this sweep's
7	// to measure. What lives here is everything specific to the freshness QUESTION. Its
8	// counterpart is adoption-issues.mjs, which owns the same three things for the coverage
9	// question; the two never import each other.
10	//
11	// WHY THE QUESTION EXISTS. Under per-project scheduling every member maintains ITSELF:
12	// its own vendored `claudinite-scheduler.yml` fires hourly, and its `baselining` task
13	// re-vendors the mount from canon. That is the right architecture — and it removed the
14	// last thing that ever looked at a member from the outside. A member whose scheduler
15	// was never vendored, whose workflow was deleted, or whose baselining has been failing
16	// for a fortnight is otherwise invisible: it still carries a declaration, so the
17	// coverage half calls it covered, and it files no failure issue because nothing runs
18	// there to fail. Self-maintenance cannot detect its own absence.
19	//
20	// WHAT `behind` MEASURES: the VERSION GAP, and nothing else. The versioned update
21	// flows stamp `engineVersion` and `packVersions` and deliberately never rewrite `ref`
22	// or `updated`, so on a well-maintained member the stamped ref is frozen at whatever
23	// commit first vendored it and its AGE measures nothing at all. A date measure over
24	// that stamp does not decay gracefully either: every member's ref ages at the same
25	// rate, so one arbitrary day the whole fleet crosses the window at once and the sweep
26	// files a drift issue per repo for a fleet that is, by versions, current (#1025).
27	//
28	// So a member is behind when its stamped engine version is below canon's, or any pack
29	// it stamps is below that pack's manifest version in canon — read out of CANON over
30	// the API, never out of the enforcer's own mount, which is itself a member and can be
31	// behind. The stamped ref is still read for what it honestly is, provenance: whether
32	// it is a commit on canon's trunk at all, which is the #328 wedge.
33	//
34	// Read-only toward every member: the only writes are the enforcer repo's own drift
35	// issues and their label.
36	
37	import { labeledIssues, DECLARATION } from '../../fleet-api.mjs';
38	
39	const LABEL = 'fleet-drift';
40	const LABEL_SPEC = { color: 'D93F0B', description: 'Covered member whose Claudinite mount has fallen behind canon' };
41	const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';
42	
43	export { LABEL, LABEL_SPEC, SCHEDULER };
44	export const FRESH = 'fresh';
45	
46	const driftTitle = (fullName) => `Claudinite mount has fallen behind on ${fullName}`;
47	const TITLE_RE = /^Claudinite mount has fallen behind on (\S+\/\S+)$/;
48	// A machine-readable state marker in the body: it lets a later run notice that the
49	// ROOT CAUSE changed (a repo that was `behind` is now `no-scheduler`) and say so,
50	// without any cross-run state to keep — the issue carries its own last verdict.
51	//
52	// The marker still spells `fleet-freshness`, the retired task that first wrote it, and
53	// must keep spelling it: every drift issue open in the enforcer right now carries that
54	// exact string, and a rename would read every one of them as `unrecorded` and comment a
55	// spurious verdict change on the first run after the merge.
56	const marker = (state) => `<!-- fleet-freshness: ${state} -->`;
57	const MARKER_RE = /<!-- fleet-freshness: ([a-z-]+) -->/;
58	
59	// --- classification (pure) ----------------------------------------------------
60	
61	// `compare` is what canon's compare endpoint said about `stampedRef → canon default
62	// branch`, normalized to { status }, or null when the ref is not a commit in canon at
63	// all. `installed` is the member's own stamp ({ engineVersion, packVersions }) and
64	// `canon` the same two numbers read out of canon for exactly the packs that stamp
65	// names. Kept free of I/O so every branch is testable directly.
66	//
67	// The precedence is about ROOT CAUSE, not the order the facts arrive in: a member with
68	// no scheduler is ALSO behind, and reporting "behind" would send the reader chasing a
69	// symptom of the missing cron.
70	export function classifyFreshness({ stampedRef, hasScheduler, compare, installed, canon }) {
71	  if (!stampedRef) {
72	    return { state: 'no-stamp', detail: `${DECLARATION} carries no claudinite.ref — the repo declares packs but has never been vendored` };
73	  }
74	  if (!hasScheduler) {
75	    return { state: 'no-scheduler', detail: `no ${SCHEDULER} — the repo has no cron, so nothing there will ever baseline it` };
76	  }
77	  if (compare === null) {
78	    return { state: 'ref-not-on-trunk', detail: `the stamped ref ${stampedRef} is not a commit in canon` };
79	  }
80	  // base=stampedRef, head=canon default branch. An ancestor reads `identical` or
81	  // `ahead`; `behind`/`diverged` means the stamp points off trunk (a force-push, a
82	  // ref vendored from a branch), which is exactly what the #328 guard refuses.
83	  if (compare.status !== 'identical' && compare.status !== 'ahead') {
84	    return { state: 'ref-not-on-trunk', detail: `the stamped ref ${stampedRef} is not an ancestor of canon's default branch (compare says "${compare.status}")` };
85	  }
86	  // A stamp carrying neither number was written before the versioned flows existed,
87	  // so it cannot be current by construction — an engine that stamps always stamps.
88	  const packIds = Object.keys(installed.packVersions);
89	  if (installed.engineVersion === null && packIds.length === 0) {
90	    return {
91	      state: 'behind',
92	      detail: `stamped at ${stampedRef} with no engineVersion and no packVersions — the mount predates the versioned update flows and has not been refreshed by them`,
93	    };
94	  }
95	  // An absent canon number is not a zero: a pack retired from canon has no manifest
96	  // to be behind, and comparing against a missing entry would report every member
97	  // that still stamps it.
98	  const gaps = [];
99	  if (installed.engineVersion !== null && canon.engineVersion !== null && installed.engineVersion < canon.engineVersion) {
100	    gaps.push(`engine v${installed.engineVersion} → v${canon.engineVersion}`);
101	  }
102	  for (const id of packIds.sort()) {
103	    const here = installed.packVersions[id];
104	    const there = canon.packVersions[id];
105	    if (typeof here === 'number' && typeof there === 'number' && here < there) {
106	      gaps.push(`${id} v${here} → v${there}`);
107	    }
108	  }
109	  if (gaps.length) return { state: 'behind', detail: `behind canon by ${gaps.join(', ')}` };
110	  return {
111	    state: FRESH,
112	    detail: `engine v${installed.engineVersion ?? '—'}, ${packIds.length} declared pack(s) at canon versions`,
113	  };
114	}
115	
116	// --- canon's own version numbers ----------------------------------------------
117	
118	// What a member is measured AGAINST, read out of canon over the API. Not out of this
119	// repo's checkout: the enforcer runs a vendored mount like any other member, so its
120	// own engine/version.mjs says what the ENFORCER received, which is a different
121	// question and can be older.
122	//
123	// Both numbers are extracted from source with an anchored line match rather than by
124	// importing the modules, because the sweep has no canon checkout to import from and
125	// the two literals are the whole payload. A file whose number cannot be read THROWS —
126	// the caller turns that into UNKNOWN for the member, which fails the run, and a
127	// guessed version would silently reclassify the fleet.
128	//
129	// Memoized per reader, promise and all: one reader is built per sweep and every
130	// member consults it, so canon is read once per distinct pack rather than once per
131	// member per pack.
132	const ENGINE_VERSION_RE = /^export const ENGINE_VERSION = (\d+);$/m;
133	const PACK_VERSION_RE = /^ {2}version: (\d+),$/m;
134	
135	export function canonVersions(gh, canonRepo) {
136	  const packs = new Map();
137	  let engine = null;
138	  const source = async (path) => {
139	    const res = await gh(`/repos/${canonRepo}/contents/${encodeURI(path)}`);
140	    if (res.status === 404) return null;
141	    if (res.status !== 200 || typeof res.json?.content !== 'string') throw new Error(`${canonRepo}:${path} returned ${res.status}`);
142	    return Buffer.from(res.json.content, 'base64').toString('utf8');
143	  };
144	  return {
145	    engine() {
146	      engine ??= (async () => {
147	        const text = await source('engine/version.mjs');
148	        const m = text && ENGINE_VERSION_RE.exec(text);
149	        if (!m) throw new Error(`canon ${canonRepo} has no readable ENGINE_VERSION in engine/version.mjs`);
150	        return Number(m[1]);
151	      })();
152	      return engine;
153	    },
154	    // null when canon carries no such pack — a pack the member still stamps but canon
155	    // has retired. Distinct from a manifest that is there and unreadable, which throws.
156	    pack(id) {
157	      if (!packs.has(id)) {
158	        packs.set(id, (async () => {
159	          const text = await source(`packs/${id}/pack.mjs`);
160	          if (text === null) return null;
161	          const m = PACK_VERSION_RE.exec(text);
162	          if (!m) throw new Error(`canon ${canonRepo} has no readable version in packs/${id}/pack.mjs`);
163	          return Number(m[1]);
164	        })());
165	      }
166	      return packs.get(id);
167	    },
168	  };
169	}
170	
171	// --- the per-member mount probe -----------------------------------------------
172	
173	// The reads this half adds on top of the declaration the roster walk already made:
174	// the scheduler workflow's presence, canon's view of the stamped ref, and canon's
175	// version numbers for the packs this member stamps. It is handed the declaration
176	// rather than re-reading it, which is the whole point of the merge — the coverage half
177	// needed the same file, and a member was being read twice.
178	//
179	// `canon` is the shared reader built once per sweep, so the per-member cost of the
180	// version half is bounded by how many packs this member declares that no earlier
181	// member did — usually none.
182	//
183	// Throws on anything indeterminate; the caller turns that into UNKNOWN for this half
184	// alone. A member whose mount cannot be probed is still one whose declaration was read,
185	// so the coverage half keeps its verdict.
186	export async function probeMount(gh, fullName, declaration, { canonRepo, canonBranch, canon }) {
187	  const stamp = declaration?.claudinite ?? {};
188	  const stampedRef = stamp.ref ?? null;
189	
190	  const wf = await gh(`/repos/${fullName}/contents/${SCHEDULER}`);
191	  if (wf.status !== 200 && wf.status !== 404) throw new Error(`${SCHEDULER} check returned ${wf.status}`);
192	  const hasScheduler = wf.status === 200;
193	
194	  const stamped = stamp.packVersions;
195	  const installed = {
196	    engineVersion: typeof stamp.engineVersion === 'number' ? stamp.engineVersion : null,
197	    packVersions: stamped && typeof stamped === 'object' && !Array.isArray(stamped) ? stamped : {},
198	  };
199	  const canonAt = { engineVersion: null, packVersions: {} };
200	
201	  let compare = null;
202	  if (stampedRef) {
203	    // per_page=1 because neither the commit list nor the counts are read — only the
204	    // status, which is all `ref-not-on-trunk` needs, and a wide-open compare over
205	    // months of canon is a needlessly large payload.
206	    const c = await gh(`/repos/${canonRepo}/compare/${stampedRef}...${canonBranch}?per_page=1`);
207	    if (c.status === 404) compare = null; // not a canon commit — classify(), not an error
208	    else if (c.status !== 200 || !c.json) throw new Error(`comparing ${stampedRef} against ${canonRepo}@${canonBranch} returned ${c.status}`);
209	    else compare = { status: c.json.status };
210	
211	    canonAt.engineVersion = await canon.engine();
212	    for (const id of Object.keys(installed.packVersions)) {
213	      const there = await canon.pack(id);
214	      if (there !== null) canonAt.packVersions[id] = there;
215	    }
216	  }
217	  return { stampedRef, hasScheduler, compare, installed, canon: canonAt };
218	}
219	
220	// --- issue bodies -------------------------------------------------------------
221	
222	const FIXES = {
223	  'no-stamp': [
224	    'Run the adoption flow against the repo (the `adopt-claudinite` skill) — it vendors the',
225	    'mount and writes the first stamp. Until then the declaration names packs whose code is',
226	    'not present, so nothing Claudinite defines actually runs there.',
227	  ],
228	  'no-scheduler': [
229	    'The repo never cut over to per-project scheduling. Vendor the scheduler',
230	    '(`vendoring/apply-vendor-set.mjs` writes it, with this repo\'s hashed cron minute) and',
231	    'confirm the workflow is enabled in the Actions tab — a repo with no cron runs no task',
232	    'at all, so every other symptom is downstream of this one.',
233	  ],
234	  'ref-not-on-trunk': [
235	    'This is a WEDGE, not a delay: `apply-vendor-set.mjs` refuses to write when the prior',
236	    'stamped ref is not an ancestor of canon HEAD (#328, the anti-rewind guard), so',
237	    'baselining fails on every run and will keep failing. Check whether canon was',
238	    'force-pushed or the mount was vendored from a branch, then re-stamp the repo at a',
239	    'commit that IS on the default branch.',
240	  ],
241	  behind: [
242	    'The scheduler workflow exists but the self-refresh is not landing. Check the repo\'s',
243	    'recent `Claudinite scheduler` runs: a disabled workflow (GitHub disables cron on repos',
244	    'with no activity for 60 days), a failing update task, or a maintenance PR that never',
245	    'merges all look like this.',
246	    '',
247	    'The gap above is read from the stamped `engineVersion`/`packVersions` against canon\'s',
248	    'own numbers, so it closes only when an update flow actually re-stamps the mount — the',
249	    'stamped `ref` is provenance and is expected never to move.',
250	  ],
251	};
252	
253	function driftBody(fullName, { state, detail }) {
254	  return [
255	    marker(state),
256	    `\`${fullName}\` is covered — it carries a tracked \`${DECLARATION}\` — but it is not keeping up with canon.`,
257	    '',
258	    `**What the sweep found (${state}):** ${detail}`,
259	    '',
260	    '**What to do**',
261	    '',
262	    ...FIXES[state],
263	    '',
264	    'This issue is converged by the daily fleet-roster task: it closes',
265	    'itself `completed` once the repo is fresh again, and `not planned` once the repo leaves the',
266	    'fleet (excluded, deleted, archived, or no longer covered). A close without either gets',
267	    'reopened while the repo stays behind.',
268	  ].join('\n');
269	}
270	
271	// --- convergence --------------------------------------------------------------
272	
273	// One issue per unhealthy member, keyed by a title that names only the repo — so the
274	// root cause can change without orphaning the thread. Deliberately quieter than the
275	// coverage half on the way in: an already-open issue gets a comment ONLY when the state
276	// actually changed, because a sweep over a fleet that is slow to heal would otherwise
277	// turn every thread into a wall of identical notes. That restraint is what lets this
278	// half ride the daily cadence rather than the weekly one it used to have.
279	export async function convergeDrift(gh, home, { unhealthy, healthySet, goneSet, dormantSet = new Set() }) {
280	  const actions = [];
281	  const { open: openIssues, closed } = await labeledIssues(gh, home, LABEL);
282	  const open = new Map(openIssues.map((i) => [i.title, i]));
283	  const wanted = new Map(unhealthy.map((u) => [u.fullName, u]));
284	
285	  for (const [fullName, verdict] of wanted) {
286	    const title = driftTitle(fullName);
287	    const existing = open.get(title);
288	    if (existing) {
289	      const was = MARKER_RE.exec(existing.body ?? '')?.[1];
290	      if (was === verdict.state) continue; // same story as yesterday — say nothing
291	      await gh(`/repos/${home}/issues/${existing.number}`, {
292	        method: 'PATCH', body: { body: driftBody(fullName, verdict) },
293	      });
294	      await gh(`/repos/${home}/issues/${existing.number}/comments`, {
295	        method: 'POST', body: { body: `The sweep's verdict changed: \`${was ?? 'unrecorded'}\` → \`${verdict.state}\`. ${verdict.detail}.` },
296	      });
297	      actions.push(`updated #${existing.number} (${fullName}: ${was ?? 'unrecorded'} → ${verdict.state})`);
298	      continue;
299	    }
300	    const prior = closed.filter((i) => i.title === title)
301	      .sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at))[0];
302	    if (prior && prior.state_reason === 'not_planned') continue; // closed as out-of-fleet; re-adding it is the standing fix
303	    if (prior) {
304	      await gh(`/repos/${home}/issues/${prior.number}`, {
305	        method: 'PATCH', body: { state: 'open', body: driftBody(fullName, verdict) },
306	      });
307	      await gh(`/repos/${home}/issues/${prior.number}/comments`, {
308	        method: 'POST', body: { body: `Reopened by the sweep: \`${fullName}\` has fallen behind again (${verdict.state}). ${verdict.detail}.` },
309	      });
310	      actions.push(`reopened #${prior.number} (${fullName}: ${verdict.state})`);
311	    } else {
312	      const { status, json } = await gh(`/repos/${home}/issues`, {
313	        method: 'POST',
314	        body: { title, body: driftBody(fullName, verdict), labels: [LABEL] },
315	      });
316	      if (status !== 201) throw new Error(`creating drift issue for ${fullName} returned ${status}`);
317	      actions.push(`opened #${json.number} (${fullName}: ${verdict.state})`);
318	    }
319	  }
320	
321	  for (const [title, issue] of open) {
322	    const m = TITLE_RE.exec(title);
323	    if (!m) continue;
324	    const fullName = m[1].toLowerCase();
325	    if (wanted.has(fullName)) continue;
326	    let reason = null; let note = null;
327	    if (healthySet.has(fullName)) {
328	      reason = 'completed'; note = 'is up to date with canon again';
329	    } else if (dormantSet.has(fullName)) {
330	      // `not planned`, not `completed`: the drift was never fixed, the repo was
331	      // taken out of the race. Closing it `completed` would claim a repair nobody
332	      // made, and leaving it open would be the nagging dormancy exists to stop.
333	      reason = 'not_planned'; note = 'has declared itself dormant — it is out of the recurring work, so the sweep no longer measures it';
334	    } else if (goneSet.has(fullName)) {
335	      reason = 'not_planned'; note = 'is no longer a covered member of the fleet (excluded, deleted, archived, or uncovered)';
336	    }
337	    if (!reason) continue; // classified UNKNOWN this run — say nothing rather than guess
338	    await gh(`/repos/${home}/issues/${issue.number}/comments`, {
339	      method: 'POST', body: { body: `Closed by the sweep: \`${m[1]}\` ${note}.` },
340	    });
341	    await gh(`/repos/${home}/issues/${issue.number}`, {
342	      method: 'PATCH', body: { state: 'closed', state_reason: reason },
343	    });
344	    actions.push(`closed #${issue.number} (${m[1]}: ${note})`);
345	  }
346	  return actions;
347	}
348	
349	// --- the freshness section of the report (pure) -------------------------------
350	
351	// Enumerates the FULL fleet: every repo lands in exactly one list — fresh (with how
352	// fresh), unhealthy (with its root cause), dormant, out of scope (with why), unknown —
353	// plus the two repos this half never measures, named rather than silently absent. A
354	// report that names only the failures leaves the reader unable to tell "fresh" from
355	// "fell out of the report". Kept free of I/O so the full-roster property is testable
356	// directly. `fresh` is `[{ fullName, detail }]`; `outOfScope` entries carry their
357	// reason inline.
358	export function renderFreshnessSummary({
359	  owner, home, canonRepo, canonBranch, fresh, unhealthy, dormant, outOfScope, unknown, actions,
360	}) {
361	  const notMeasured = [`\`${home}\` — the enforcer, swept by its own scheduler`];
362	  if (canonRepo.toLowerCase() !== home.toLowerCase()) notMeasured.push(`\`${canonRepo}\` — canon, with no vendored mount to be stale`);
363	  return [
364	    `# Fleet freshness sweep — ${owner} (measured by stamped versions against canon: ${canonRepo}@${canonBranch})`,
365	    '',
366	    '| fresh | behind | no scheduler | no stamp | off trunk | dormant | out of scope | unknown |',
367	    '| --- | --- | --- | --- | --- | --- | --- | --- |',
368	    `| ${fresh.length} | ${unhealthy.filter((u) => u.state === 'behind').length} | `
369	      + `${unhealthy.filter((u) => u.state === 'no-scheduler').length} | `
370	      + `${unhealthy.filter((u) => u.state === 'no-stamp').length} | `
371	      + `${unhealthy.filter((u) => u.state === 'ref-not-on-trunk').length} | ${dormant.length} | ${outOfScope.length} | ${unknown.length} |`,
372	    '',
373	    unhealthy.length
374	      ? `**Behind (drift issue open):**\n${unhealthy.map((u) => `- \`${u.fullName}\` — **${u.state}**: ${u.detail}`).join('\n')}`
375	      : '**Every covered member is up to date 🎉**',
376	    fresh.length
377	      ? `**Fresh:**\n${fresh.map((f) => `- \`${f.fullName}\` — ${f.detail}`).join('\n')}`
378	      : '**Fresh:** none',
379	    dormant.length ? `**Dormant (self-declared, not measured):** ${dormant.join(', ')}` : '',
380	    outOfScope.length ? `**Out of scope (not covered members):** ${outOfScope.join(', ')}` : '',
381	    unknown.length ? `**UNKNOWN (probe errored — fix the token/scope):** ${unknown.join('; ')}` : '',
382	    `**Not measured:** ${notMeasured.join('; ')}`,
383	    actions.length ? `**Issue actions:** ${actions.join('; ')}` : '**Issue actions:** none (converged)',
384	  ].filter(Boolean).join('\n');
385	}
