349	// --- the freshness section of the report (pure) -------------------------------
350	
351	// Enumerates the FULL fleet: every repo lands in exactly one list — fresh (with how
352	// fresh), unhealthy (with its root cause), dormant, out of scope (with why), unknown —
353	// plus the two repos this half never measures, named rather than silently absent. A
354	// report that names only the failures leaves the reader unable to tell "fresh" from
355	// "fell out of the report". Kept free of I/O so the full-roster property is testable
356	// directly. `fresh` is `[{ fullName, detail }]`; `outOfScope` entries carry their
357	// reason inline.
358	export function renderFreshnessSummary({
359	  owner, home, canonRepo, canonBranch, fresh, unhealthy, dormant, outOfScope, unknown, actions,
360	}) {
361	  const notMeasured = [`\`${home}\` — the enforcer, swept by its own scheduler`];
362	  if (canonRepo.toLowerCase() !== home.toLowerCase()) notMeasured.push(`\`${canonRepo}\` — canon, with no vendored mount to be stale`);
363	  return [
364	    `# Fleet freshness sweep — ${owner} (measured by stamped versions against canon: ${canonRepo}@${canonBranch})`,
365	    '',
366	    '| fresh | behind | no scheduler | no stamp | off trunk | dormant | out of scope | unknown |',
367	    '| --- | --- | --- | --- | --- | --- | --- | --- |',
368	    `| ${fresh.length} | ${unhealthy.filter((u) => u.state === 'behind').length} | `
369	      + `${unhealthy.filter((u) => u.state === 'no-scheduler').length} | `
370	      + `${unhealthy.filter((u) => u.state === 'no-stamp').length} | `
371	      + `${unhealthy.filter((u) => u.state === 'ref-not-on-trunk').length} | ${dormant.length} | ${outOfScope.length} | ${unknown.length} |`,
372	    '',
373	    unhealthy.length
374	      ? `**Behind (drift issue open):**\n${unhealthy.map((u) => `- \`${u.fullName}\` — **${u.state}**: ${u.detail}`).join('\n')}`
375	      : '**Every covered member is up to date 🎉**',
376	    fresh.length
377	      ? `**Fresh:**\n${fresh.map((f) => `- \`${f.fullName}\` — ${f.detail}`).join('\n')}`
378	      : '**Fresh:** none',
379	    dormant.length ? `**Dormant (self-declared, not measured):** ${dormant.join(', ')}` : '',
380	    outOfScope.length ? `**Out of scope (not covered members):** ${outOfScope.join(', ')}` : '',
381	    unknown.length ? `**UNKNOWN (probe errored — fix the token/scope):** ${unknown.join('; ')}` : '',
382	    `**Not measured:** ${notMeasured.join('; ')}`,
383	    actions.length ? `**Issue actions:** ${actions.join('; ')}` : '**Issue actions:** none (converged)',
384	  ].filter(Boolean).join('\n');
385	}
